import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom'; 
import { fetchMachineById } from '../services/api';

export default function MachineDetailPage() { 
  const { id } = useParams(); 
  const [machine, setMachine] = useState(null);

  useEffect(() => { 
    let mounted = true; const load = async () => { 
      const data = await fetchMachineById(id); if (mounted) setMachine(data); 
    }; 
    load(); 
    return () => (mounted = false); 
  }, 
  [id]
);

if (!machine) return <div>Загрузка...</div>; 
return ( <div> <h3>Характеристики машины</h3>
</div> ); 
}
